#include "../Source/PluginProcessor.h"
#include <iostream>
#include <stdexcept>
int runInstalledBankSmoke(const juce::File& catalogue){try{
 const auto require=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};const auto design=juce::JSON::parse(catalogue);require(int(design["active_presets"])==421,"Missing installed-bank catalogue");
 const auto directory=juce::File::getSpecialLocation(juce::File::tempDirectory).getNonexistentChildFile("InfinityInstalled094",{},false);auto p=std::make_unique<SpaceInfinityProcessor>(directory,true);
 require(p->bundledPresetError.isEmpty(),"Automatic constructor bank provision failed");auto& bank=p->presetBank();require(bank.entries().size()==422,"Fresh installation lacks the complete curated bank");
 for(const auto& name:juce::StringArray{"SPACE_INFINITY_Heritage_200.zip","SPACE_INFINITY_Lush_Trance_20.zip","SPACE_INFINITY_Orbit_Voices.zip"}){const auto marker=directory.getChildFile("bundled_"+name.replaceCharacter('.','_')+".sha256");require(marker.loadFileAsString().trim()==design["banks"][juce::Identifier(name)]["sha256"].toString(),"Embedded bank differs from calibrated catalogue");}
 juce::StringArray keys;int sampled=0;for(size_t i=0;i<bank.entries().size();++i){const auto entry=bank.entries()[i];require(!keys.contains(entry.key),"Duplicate installed preset");keys.add(entry.key);if(entry.factory==0)continue;require(p->loadBankPreset(int(i)).wasOk(),"Installed preset does not load");const auto settings=design["settings"][juce::Identifier(entry.key)];require(settings.isObject(),"Unexpected preset or missing calibration");require(entry.tags.contains("Level Matched 094"),"Installed preset missing its current revision tag");for(const auto& value:settings.getDynamicObject()->getProperties()){const auto* parameter=p->state.getRawParameterValue(value.name.toString());require(parameter&&std::abs(parameter->load()-float(value.value))<.0001f,"Installed preset parameters differ from calibrated data");}
  if(entry.key.startsWith("Uuser_orbitvoices093_")){++sampled;require(p->state.state.getProperty("sampleName").toString().startsWith("Infinity_"),"Sampled preset has no renamed embedded source");require(p->state.getRawParameterValue("sampleStereo")->load()==1,"Sampled preset lost stereo fidelity");}
 }
 require(sampled==48,"New sampled presets missing from automatic installation");require(p->ensureBundledPresets().wasOk()&&bank.entries().size()==422,"Repeated startup duplicates or resurrects bank entries");
 // Reinstallation must preserve a real user sound replacement and metadata edit.
 const auto key=juce::String("Uuser_orbitvoices093_O013");int index=bank.indexForKey(key);require(index>=0,"Editable sample fixture missing");require(p->loadBankPreset(index).wasOk(),"Editable fixture load");auto* gain=p->state.getParameter("presetReferenceGain");gain->setValueNotifyingHost(gain->convertTo0to1(-17));require(p->replaceBankPreset(index).wasOk(),"User replacement failed");require(bank.updateDetails(index,"Owner custom lead","Owner","Personal").wasOk(),"User metadata edit failed");require(p->ensureBundledPresets().wasOk(),"Reinstall failed");index=bank.indexForKey(key);require(bank.entries()[size_t(index)].name=="Owner custom lead"&&p->loadBankPreset(index).wasOk()&&p->state.getRawParameterValue("presetReferenceGain")->load()==-17,"Reinstall overwrites user changes");
 p.reset();directory.deleteRecursively();std::cout<<"Fresh automatic bank: 421 calibrated presets + Init; 48 embedded sample presets, bank hashes, repeat startup and user replacements verified\n";return 0;
}catch(const std::exception& e){std::cerr<<"Installed bank: "<<e.what()<<std::endl;return 94;}}
